UPDATE payment_reconciliation_job
SET status = 'PROCESSING', locked_at = now(), updated_at = now()
WHERE job_id = #{jobId}

UPDATE payment_reconciliation_job
SET status = 'DONE', locked_at = NULL, updated_at = now()
WHERE job_id = #{jobId}

UPDATE payment_reconciliation_job
SET status = 'FAILED', last_error = #{lastError}, locked_at = NULL, updated_at = now()
WHERE job_id = #{jobId}
